@Override
  public void save(CompoundTag tag) {
    Map<String, Float> values = this.getValues();

    if (values != null) {

      for (Map.Entry<String, Float> group : values.entrySet()) {
        tag.putFloat(group.getKey(), group.getValue());
      }
    }
    ListTag list = new ListTag();
    Map<Attribute, Set<UUID>> modifiers = this.getModifiers();

    if (modifiers != null) {

      for (Map.Entry<Attribute, Set<UUID>> modifier : modifiers.entrySet()) {
        CompoundTag attributeTag = new CompoundTag();
        attributeTag.put("AttributeName", StringTag.valueOf(
            Objects.requireNonNull(Services.REGISTRY.getAttributeKey(modifier.getKey()))
                .toString()));
        ListTag uuids = new ListTag();

        for (UUID uuid : modifier.getValue()) {
          uuids.add(StringTag.valueOf(uuid.toString()));
        }
        attributeTag.put("UUIDs", uuids);
        list.add(attributeTag);
      }
    }
    tag.put("Modifiers", list);
    list = new ListTag();
    Set<Item> eaten = this.getEaten();

    if (eaten != null) {

      for (Item item : eaten) {
        ResourceLocation rl = Services.REGISTRY.getItemKey(item);

        if (rl != null) {
          list.add(StringTag.valueOf(rl.toString()));
        }
      }
    }
    tag.put("Eaten", list);
    tag.putBoolean("Active", this.isActive());
  }

@Override
  public void load(CompoundTag tag) {
    Map<String, Float> groups = new HashMap<>();

    DietSuites.getSuite(this.player.level(), this.suite).ifPresent(suite -> {

      for (IDietGroup group : suite.getGroups()) {
        String name = group.getName();
        float amount = tag.contains(name) ? tag.getFloat(name) : group.getDefaultValue();
        groups.put(name, Mth.clamp(amount, 0.0f, 1.0f));
      }
    });
    ListTag list = tag.getList("Modifiers", Tag.TAG_COMPOUND);
    Map<Attribute, Set<UUID>> modifiers = new HashMap<>();

    for (int i = 0; i < list.size(); i++) {
      CompoundTag attributeTag = list.getCompound(i);
      Attribute att = Services.REGISTRY.getAttribute(
          new ResourceLocation(attributeTag.getString("AttributeName"))).orElse(null);

      if (att != null) {
        Set<UUID> uuids = new HashSet<>();
        ListTag uuidList = attributeTag.getList("UUIDs", Tag.TAG_STRING);

        for (int j = 0; j < uuidList.size(); j++) {
          uuids.add(UUID.fromString(uuidList.getString(j)));
        }
        modifiers.put(att, uuids);
      }
    }
    list = tag.getList("Eaten", Tag.TAG_STRING);
    Set<Item> eaten = new HashSet<>();

    for (int i = 0; i < list.size(); i++) {
      String s = list.getString(i);
      ResourceLocation rl = new ResourceLocation(s);
      Services.REGISTRY.getItem(rl).ifPresent(eaten::add);
    }
    this.setEaten(eaten);
    this.setModifiers(modifiers);
    this.setValues(groups);
    this.setActive(!tag.contains("Active") || tag.getBoolean("Active"));
  }

@Override
  public void copy(Player oldPlayer, boolean wasDeath) {
    Services.CAPABILITY.get(this.player)
        .ifPresent(diet -> Services.CAPABILITY.get(oldPlayer).ifPresent(originalDiet -> {
          Map<String, Float> originalValues = originalDiet.getValues();
          DietSuites.getSuite(this.player.level(), this.suite).ifPresent(suite -> {

            for (IDietGroup group : suite.getGroups()) {
              String id = group.getName();
              float originalValue = originalValues.getOrDefault(id, group.getDefaultValue());
              float newValue = originalValue;

              if (wasDeath) {

                if (DietConfig.SERVER.deathPenaltyMethod.get() ==
                    DietConfig.DeathPenaltyMethod.RESET) {
                  newValue = group.getDefaultValue();
                } else {
                  float loss = (float) DietConfig.SERVER.deathPenaltyLoss.get() / 100F;

                  if (DietConfig.SERVER.deathPenaltyMethod.get() ==
                      DietConfig.DeathPenaltyMethod.AMOUNT) {
                    newValue -= loss;
                  } else {
                    newValue *= (1 - loss);
                  }
                  newValue = Math.min(originalValue,
                      Math.max(newValue, (float) DietConfig.SERVER.deathPenaltyMin.get() / 100F));
                }
              }
              diet.setValue(id, newValue);
            }
          });
          diet.setActive(originalDiet.isActive());

          if (!wasDeath) {
            diet.setModifiers(originalDiet.getModifiers());
          }
        }));
  }

public static void register(CommandDispatcher<CommandSourceStack> dispatcher) {
    final int opPermissionLevel = 2;
    LiteralArgumentBuilder<CommandSourceStack> dietCommand =
        Commands.literal("diet").requires(player -> player.hasPermission(opPermissionLevel));

    dietCommand.then(Commands.literal("get")
        .then(Commands.argument("player", EntityArgument.player())
            .then(Commands.argument("group", DietGroupArgument.group())
                .executes(ctx -> get(ctx.getSource(), EntityArgument.getPlayer(ctx, "player"),
                    DietGroupArgument.getGroup(ctx, "group"))))));

    dietCommand.then(Commands.literal("set")
        .then(Commands.argument("player", EntityArgument.player())
            .then(Commands.argument("group", DietGroupArgument.group())
                .then(Commands.argument("value", FloatArgumentType.floatArg(0.0f, 1.0f))
                    .executes(ctx -> set(ctx.getSource(), EntityArgument.getPlayer(ctx, "player"),
                        FloatArgumentType.getFloat(ctx, "value"),
                        DietGroupArgument.getGroup(ctx, "group")))))));

    dietCommand.then(Commands.literal("add")
        .then(Commands.argument("player", EntityArgument.player())
            .then(Commands.argument("group", DietGroupArgument.group())
                .then(Commands.argument("value", FloatArgumentType.floatArg(0.0f, 1.0f))
                    .executes(
                        ctx -> modify(ctx.getSource(), EntityArgument.getPlayer(ctx, "player"),
                            FloatArgumentType.getFloat(ctx, "value"),
                            DietGroupArgument.getGroup(ctx, "group")))))));

    dietCommand.then(Commands.literal("subtract")
        .then(Commands.argument("player", EntityArgument.player())
            .then(Commands.argument("group", DietGroupArgument.group())
                .then(Commands.argument("value", FloatArgumentType.floatArg(0.0f, 1.0f))
                    .executes(
                        ctx -> modify(ctx.getSource(), EntityArgument.getPlayer(ctx, "player"),
                            -1 * FloatArgumentType.getFloat(ctx, "value"),
                            DietGroupArgument.getGroup(ctx, "group")))))));

    dietCommand.then(Commands.literal("reset")
        .then(Commands.argument("player", EntityArgument.player())
            .executes(ctx -> reset(ctx.getSource(), EntityArgument.getPlayer(ctx, "player")))));

    dietCommand.then(Commands.literal("pause")
        .then(Commands.argument("player", EntityArgument.player())
            .executes(
                ctx -> active(ctx.getSource(), EntityArgument.getPlayer(ctx, "player"), false))));

    dietCommand.then(Commands.literal("resume")
        .then(Commands.argument("player", EntityArgument.player())
            .executes(
                ctx -> active(ctx.getSource(), EntityArgument.getPlayer(ctx, "player"), true))));

    dietCommand.then(Commands.literal("clear")
        .then(Commands.argument("player", EntityArgument.player())
            .executes(ctx -> clear(ctx.getSource(), EntityArgument.getPlayer(ctx, "player")))));

    LiteralArgumentBuilder<CommandSourceStack> exportArg =
        Commands.literal("export").executes(ctx -> export(ctx.getSource(), DietCsv.ExportMode.ALL));

    exportArg.then(Commands.literal("group").then(
        Commands.argument("group", DietGroupArgument.group()).executes(
            ctx -> export(ctx.getSource(), DietGroupArgument.getGroup(ctx, "group")))));

    exportArg.then(Commands.literal("mod_id").then(
        Commands.argument("mod_id", Services.REGISTRY.getModIdArgument())
            .executes(ctx -> export(ctx.getSource(), DietCsv.ExportMode.MOD_ID,
                StringArgumentType.getString(ctx, "mod_id")))));

    exportArg.then(Commands.literal("uncategorized")
        .executes(ctx -> export(ctx.getSource(), DietCsv.ExportMode.UNCATEGORIZED)));

    exportArg.then(Commands.literal("trails")
        .executes(ctx -> export(ctx.getSource(), DietCsv.ExportMode.TRAILS)));

    dietCommand.then(exportArg);

    dispatcher.register(dietCommand);
  }

private static int get(CommandSourceStack sender, ServerPlayer player, IDietGroup group) {
    Services.CAPABILITY.get(player).ifPresent(diet -> {
      float amount = diet.getValue(group.getName());
      sender.sendSuccess(
          () -> Component.translatable("commands." + DietConstants.MOD_ID + ".get.success",
              Component.translatable(
                  "groups." + DietConstants.MOD_ID + "." + group.getName() + ".name"), amount * 100,
              player.getName()), true);
    });
    return Command.SINGLE_SUCCESS;
  }

private static int set(CommandSourceStack sender, ServerPlayer player, float value,
                         IDietGroup group) {
    Services.CAPABILITY.get(player).ifPresent(diet -> {
      if (diet.getValues().containsKey(group.getName())) {
        diet.setValue(group.getName(), value);
        diet.sync();
        sender.sendSuccess(
            () -> Component.translatable("commands." + DietConstants.MOD_ID + ".set.success",
                Component.translatable(
                    "groups." + DietConstants.MOD_ID + "." + group.getName() + ".name"),
                value * 100, player.getName()), true);
      }
    });
    return Command.SINGLE_SUCCESS;
  }

private static int modify(CommandSourceStack sender, ServerPlayer player, float amount,
                            IDietGroup group) {

    if (amount != 0) {
      Services.CAPABILITY.get(player).ifPresent(diet -> {
        if (diet.getValues().containsKey(group.getName())) {
          diet.setValue(group.getName(), diet.getValue(group.getName()) + amount);
          diet.sync();
          String arg = amount > 0 ? "add" : "remove";
          sender.sendSuccess(() -> Component.translatable(
              "commands." + DietConstants.MOD_ID + "." + arg + ".success", Component.translatable(
                  "groups." + DietConstants.MOD_ID + "." + group.getName() + ".name"), amount * 100,
              player.getName()), true);
        }
      });
    }
    return Command.SINGLE_SUCCESS;
  }

private static int reset(CommandSourceStack sender, ServerPlayer player) {
    Services.CAPABILITY.get(player).ifPresent(diet -> {
      DietSuites.getSuite(player.level(), diet.getSuite()).ifPresent(suite -> {

        for (IDietGroup group : suite.getGroups()) {
          diet.setValue(group.getName(), group.getDefaultValue());
        }
      });
      diet.sync();
      sender.sendSuccess(
          () -> Component.translatable("commands." + DietConstants.MOD_ID + ".reset.success",
              player.getName()), true);
    });
    return Command.SINGLE_SUCCESS;
  }

private static int active(CommandSourceStack sender, ServerPlayer player, boolean flag) {
    Services.CAPABILITY.get(player).ifPresent(diet -> {
      diet.setActive(flag);
      diet.sync();
      String arg = flag ? "resume" : "pause";
      sender.sendSuccess(
          () -> Component.translatable("commands." + DietConstants.MOD_ID + "." + arg + ".success",
              player.getName()), true);
    });
    return Command.SINGLE_SUCCESS;
  }

private static int clear(CommandSourceStack sender, ServerPlayer player) {

    for (AttributeInstance instance : player.getAttributes().getDirtyAttributes()) {

      for (AttributeModifier attributeModifier : instance.getModifiers()) {

        if (attributeModifier.getName().equals("Diet group effect")) {
          instance.removeModifier(attributeModifier.getId());
        }
      }
    }
    sender.sendSuccess(
        () -> Component.translatable("commands." + DietConstants.MOD_ID + ".clear.success",
            player.getName()), true);
    return Command.SINGLE_SUCCESS;
  }

private static int export(CommandSourceStack sender, IDietGroup group) {

    if (sender.getEntity() instanceof Player) {
      sender.sendSuccess(
          () -> Component.translatable("commands." + DietConstants.MOD_ID + ".export.started"),
          true);
      DietCsv.writeGroup((Player) sender.getEntity(), group);
      sender.sendSuccess(
          () -> Component.translatable("commands." + DietConstants.MOD_ID + ".export.finished"),
          true);
    }
    return Command.SINGLE_SUCCESS;
  }

private static int export(CommandSourceStack sender, DietCsv.ExportMode mode, String... args) {

    if (sender.getEntity() instanceof Player player) {
      sender.sendSuccess(
          () -> Component.translatable("commands." + DietConstants.MOD_ID + ".export.started"),
          true);

      if (mode == DietCsv.ExportMode.ALL) {
        DietCsv.write(player, "");
      } else if (mode == DietCsv.ExportMode.MOD_ID) {
        DietCsv.write(player, args[0]);
      } else if (mode == DietCsv.ExportMode.UNCATEGORIZED) {
        DietCsv.writeUncategorized(player);
      } else if (mode == DietCsv.ExportMode.TRAILS) {
        DietCsv.writeTrails(player);
      }
      sender.sendSuccess(
          () -> Component.translatable("commands." + DietConstants.MOD_ID + ".export.finished"),
          true);
    }
    return Command.SINGLE_SUCCESS;
  }

public static void write(Player player, String modId) {
    List<String[]> data = new ArrayList<>();

    for (Item item : Services.REGISTRY.getItems()) {
      ResourceLocation rl = Services.REGISTRY.getItemKey(item);

      if (rl != null) {

        if (!modId.isEmpty() && !rl.getNamespace().equals(modId)) {
          continue;
        }
        writeStack(player, item.getDefaultInstance(), data);
      }
    }
    write(data);
  }

public static void writeGroup(Player player, IDietGroup group) {
    List<String[]> data = new ArrayList<>();
    for (Item tagItem : Services.REGISTRY.getTagItems(group.getTag())) {
      writeStack(player, tagItem.getDefaultInstance(), data);
    }
    write(data);
  }

public static void writeUncategorized(Player player) {
    List<String[]> data = new ArrayList<>();

    for (Item item : Services.REGISTRY.getItems()) {
      ItemStack stack = item.getDefaultInstance();
      FoodProperties food = Services.REGISTRY.getFoodProperties(stack, player);

      if (food != null && food.getNutrition() > 0 &&
          DietApi.getInstance().getGroups(player, stack).isEmpty()) {
        data.add(new String[] {getName(item)});
      }
    }
    write(data);
  }

public static void writeTrails(Player player) {
    List<String[]> data = new ArrayList<>();

    for (Item item : Services.REGISTRY.getItems()) {

      if (!DietApi.getInstance().getGroups(player, item.getDefaultInstance()).isEmpty()) {
        List<Item> trail = DietValueGenerator.getTrail(item);

        if (!trail.isEmpty()) {
          data.add(new String[] {getName(item), getName(trail.get(0))});

          for (int i = 1; i < trail.size(); i++) {
            data.add(new String[] {"", getName(trail.get(i))});
          }
        }
      }
    }
    write(data);
  }

private static void writeStack(Player player, ItemStack stack, List<String[]> data) {
    Map<IDietGroup, Float> result = DietApi.getInstance().get(player, stack).get();
    List<Map.Entry<IDietGroup, Float>> list = Lists.newArrayList(result.entrySet());

    if (!list.isEmpty()) {
      Map.Entry<IDietGroup, Float> entry = list.get(0);
      data.add(new String[] {getName(stack.getItem()), entry.getKey().getName(),
          entry.getValue().toString()});

      for (int i = 1; i < list.size(); i++) {
        Map.Entry<IDietGroup, Float> entry2 = list.get(i);
        data.add(new String[] {"", entry2.getKey().getName(), entry2.getValue().toString()});
      }
    }
  }

private static void write(List<String[]> data) {
    Path output = Paths.get(Services.PLATFORM.getGameDir() + "/logs/diet.csv");

    try (BufferedWriter writer = Files.newBufferedWriter(output, StandardCharsets.UTF_8)) {

      for (String[] datum : data) {
        writer.write(toCsv(datum));
        writer.newLine();
      }
    } catch (IOException e) {
      DietConstants.LOG.error("Error attempting to export diet information, aborting...");
      e.printStackTrace();
    }
  }

private static String toCsv(String[] data) {
    return String.join(",", data);
  }

