@Override
  protected void apply(@Nonnull Map<ResourceLocation, JsonElement> object,
                       @Nonnull ResourceManager resourceManager,
                       @Nonnull ProfilerFiller profilerFiller) {
    Map<String, DietSuite.Builder> map = new HashMap<>();
    uuidSuffix = 0;

