	}

@SubscribeEvent
	public static void onClone(PlayerEvent.Clone event) {
		if (event.isWasDeath() && SOLCarrotConfig.shouldResetOnDeath()) return;

		var originalPlayer = event.getOriginal();
		originalPlayer.reviveCaps(); // so we can access the capabilities; entity will get removed either way
		var original = FoodList.get(originalPlayer);
		var newInstance = FoodList.get(event.getEntity());
		newInstance.deserializeNBT(original.serializeNBT());
		// can't sync yet; client hasn't attached capabilities yet

		originalPlayer.invalidateCaps();
	}

@SubscribeEvent
	public static void onPlayerRespawn(PlayerEvent.PlayerRespawnEvent event) {
		syncFoodList(event.getEntity());
	}

public static void syncFoodList(Player player) {
		if (player.level().isClientSide) return;

		var target = (ServerPlayer) player;
		SOLCarrot.channel.sendTo(
			new FoodListMessage(FoodList.get(player)),
			target.connection.connection,
			NetworkDirection.PLAY_TO_CLIENT
		);

		MaxHealthHandler.updateFoodHPModifier(player);
	}

public FoodInstance(Item item) {
		this.item = item;
	}

@Nullable
	public static FoodInstance decode(String encoded) {
		ResourceLocation name = new ResourceLocation(encoded);

		// TODO it'd be nice to store (and maybe even count) references to missing items, in case the mod is added back in later
		Item item = ForgeRegistries.ITEMS.getValue(name);
		if (item == null) {
			SOLCarrot.LOGGER.warn("attempting to load item into food list that is no longer registered: " + encoded + " (removing from list)");
			return null;
		}

		if (!item.isEdible()) {
			SOLCarrot.LOGGER.warn("attempting to load item into food list that is no longer edible: " + encoded + " (ignoring in case it becomes edible again later)");
		}

		return new FoodInstance(item);
	}

@Nullable
	public String encode() {
		return Optional.ofNullable(ForgeRegistries.ITEMS.getKey(item))
			.map(ResourceLocation::toString)
			.orElse(null);
	}

@Override
	public int hashCode() {
		return item.hashCode();
	}

@Override
	public boolean equals(Object obj) {
		if (!(obj instanceof FoodInstance other)) return false;

		return item.equals(other.item);
	}

public Item getItem() {
		return item;
	}

public static FoodList get(Player player) {
		return (FoodList) player.getCapability(SOLCarrotAPI.foodCapability)
			.orElseThrow(FoodListNotFoundException::new);
	}

@Override
	public <T> LazyOptional<T> getCapability(Capability<T> capability, @Nullable Direction side) {
		return capability == SOLCarrotAPI.foodCapability ? capabilityOptional.cast() : LazyOptional.empty();
	}

@Override
	public CompoundTag serializeNBT() {
		var tag = new CompoundTag();

		var list = new ListTag();
		foods.stream()
			.map(FoodInstance::encode)
			.filter(Objects::nonNull)
			.map(StringTag::valueOf)
			.forEach(list::add);
		tag.put(NBT_KEY_FOOD_LIST, list);

		return tag;
	}

@Override
	public void deserializeNBT(CompoundTag tag) {
		var list = tag.getList(NBT_KEY_FOOD_LIST, Tag.TAG_STRING);

		foods.clear();
		list.stream()
			.map(nbt -> (StringTag) nbt)
			.map(StringTag::getAsString)
			.map(FoodInstance::decode)
			.filter(Objects::nonNull)
			.forEach(foods::add);

		invalidateProgressInfo();
	}

public boolean addFood(Item food) {
		boolean wasAdded = foods.add(new FoodInstance(food)) && SOLCarrotConfig.shouldCount(food);
		invalidateProgressInfo();
		return wasAdded;
	}

@Override
	public boolean hasEaten(Item food) {
		if (!food.isEdible()) return false;
		return foods.contains(new FoodInstance(food));
	}

public void clearFood() {
		foods.clear();
		invalidateProgressInfo();
	}

public Set<FoodInstance> getEatenFoods() {
		return new HashSet<>(foods);
	}

@Override
	public int getEatenFoodCount() {
		return foods.size();
	}

public ProgressInfo getProgressInfo() {
		if (cachedProgressInfo == null) {
			cachedProgressInfo = new ProgressInfo(this);
		}
		return cachedProgressInfo;
	}

public void invalidateProgressInfo() {
		cachedProgressInfo = null;
	}

public FoodListNotFoundException() {
			super("Player must have food capability attached, but none was found.");
		}

@SubscribeEvent
	public static void onFoodEaten(LivingEntityUseItemEvent.Finish event) {
		if (!(event.getEntity() instanceof Player player)) return;

		var isClientSide = player.level().isClientSide;

		if (SOLCarrotConfig.limitProgressionToSurvival() && player.isCreative()) return;

		var usedItem = event.getItem().getItem();
		if (!usedItem.isEdible()) return;

		FoodList foodList = FoodList.get(player);
		boolean hasTriedNewFood = foodList.addFood(usedItem);

		// check this before syncing, because the sync entails an hp update
		boolean newMilestoneReached = MaxHealthHandler.updateFoodHPModifier(player);

		CapabilityHandler.syncFoodList(player);
		var progressInfo = foodList.getProgressInfo();

		if (newMilestoneReached) {
			if (isClientSide && SOLCarrotConfig.shouldPlayMilestoneSounds()) {
				// passing the player makes it not play for some reason
				player.level().playSound(
					player,
					player.blockPosition(),
					SoundEvents.PLAYER_LEVELUP, SoundSource.PLAYERS,
					1.0F, 1.0F
				);
			}

			if (isClientSide && SOLCarrotConfig.shouldSpawnMilestoneParticles()) {
				spawnParticles(player, ParticleTypes.HEART, 12);

				if (progressInfo.hasReachedMax()) {
					spawnParticles(player, ParticleTypes.HAPPY_VILLAGER, 16);
				}
			}

			var heartsDescription = localizedQuantityComponent("message", "hearts", SOLCarrotConfig.getHeartsPerMilestone());

			if (isClientSide && SOLCarrotConfig.shouldShowProgressAboveHotbar()) {
				String messageKey = progressInfo.hasReachedMax() ? "finished.hotbar" : "milestone_achieved";
				player.displayClientMessage(localizedComponent("message", messageKey, heartsDescription), true);
			} else {
				showChatMessage(player, ChatFormatting.DARK_AQUA, localizedComponent("message", "milestone_achieved", heartsDescription));
				if (progressInfo.hasReachedMax()) {
					showChatMessage(player, ChatFormatting.GOLD, localizedComponent("message", "finished.chat"));
				}
			}
		} else if (hasTriedNewFood) {
			if (isClientSide && SOLCarrotConfig.shouldSpawnIntermediateParticles()) {
				spawnParticles(player, ParticleTypes.END_ROD, 12);
			}
		}
	}

private static void spawnParticles(Player player, ParticleOptions type, int count) {
		// hacky way to reuse the existing logic for randomizing particle spawn positions
		var connection = Minecraft.getInstance().getConnection();
		assert connection != null;
		connection.handleParticleEvent(new ClientboundLevelParticlesPacket(
			type, false,
			player.getX(), player.getY() + player.getEyeHeight(), player.getZ(),
			0.5F, 0.5F, 0.5F,
			0.0F, count
		));
	}

private static void showChatMessage(Player player, ChatFormatting color, Component message) {
		var component = localizedComponent("message", "chat_wrapper", message)
			.withStyle(color);
		player.displayClientMessage(component, false);
	}

@SubscribeEvent
	public static void onPlayerLogin(PlayerEvent.PlayerLoggedInEvent event) {
		updateFoodHPModifier(event.getEntity());
	}

@SubscribeEvent
	public static void onPlayerClone(PlayerEvent.Clone event) {
		var prevModifier = getHealthModifier(event.getOriginal());
		if (prevModifier == null) return;

		updateHealthModifier(event.getEntity(), prevModifier);
	}

public static boolean updateFoodHPModifier(Player player) {
		var prevModifier = getHealthModifier(player);

		int healthPenalty = 2 * (SOLCarrotConfig.getBaseHearts() - 10);

		ProgressInfo progressInfo = FoodList.get(player).getProgressInfo();
		int milestonesAchieved = progressInfo.milestonesAchieved();
		int addedHealthFromFood = milestonesAchieved * 2 * SOLCarrotConfig.getHeartsPerMilestone();

		double totalHealthModifier = healthPenalty + addedHealthFromFood;
		boolean hasChanged = prevModifier == null || prevModifier.getAmount() != totalHealthModifier;

		if (!player.level().isClientSide) {
			AttributeModifier modifier = new AttributeModifier(
				MILESTONE_HEALTH_MODIFIER_ID,
				"Health Gained from Trying New Foods",
				totalHealthModifier,
				AttributeModifier.Operation.ADDITION
			);

			updateHealthModifier(player, modifier);
		}

		return hasChanged;
	}

@Nullable
	private static AttributeModifier getHealthModifier(Player player) {
		return maxHealthAttribute(player).getModifier(MILESTONE_HEALTH_MODIFIER_ID);
	}

private static void updateHealthModifier(Player player, AttributeModifier modifier) {
		var oldMax = player.getMaxHealth();

		var attribute = maxHealthAttribute(player);
		attribute.removeModifier(modifier);
		attribute.addPermanentModifier(modifier);

		var newHealth = player.getHealth() * player.getMaxHealth() / oldMax;
		if (!HAS_FIRST_AID) { // This workaround breaks First Aid because it tries to distribute the health change and may kill the player that way.
			// because apparently it doesn't update unless changed
			player.setHealth(1f);
		}
		// adjust current health proportionally to increase in max health
		player.setHealth(newHealth);
	}

private static AttributeInstance maxHealthAttribute(Player player) {
		return Objects.requireNonNull(player.getAttribute(Attributes.MAX_HEALTH));
	}

ProgressInfo(FoodList foodList) {
		foodsEaten = (int) foodList.getEatenFoods().stream()
			.filter(food -> SOLCarrotConfig.shouldCount(food.item))
			.count();
	}

public boolean hasReachedMax() {
		return foodsEaten >= SOLCarrotConfig.highestMilestone();
	}

public int nextMilestone() {
		return hasReachedMax() ? -1 : SOLCarrotConfig.milestone(milestonesAchieved());
	}

public int foodsUntilNextMilestone() {
		return nextMilestone() - foodsEaten;
	}

public int milestonesAchieved() {
		return (int) SOLCarrotConfig.getMilestones().stream()
			.filter(milestone -> foodsEaten >= milestone).count();
	}
